result:
.poptipOn{
  display: none;
}
/deep/textarea.ivu-input{
  resize: none;
}
.batchItem{
  padding-left: 2px;
  padding-right: 2px;
  .title{
    font-size: 13px;
    color: #333;
    font-weight: 400;
    margin-top: 6px;
  }
  .tips{
    font-size: 12px;
    color: #999999;
    font-weight: 400;
    margin-top: 3px;
    margin-bottom: 10px;
  }
  .batchBnt{
    margin-top: 12px;
  }
}
.select-word{
  margin-bottom: 20px;
  .c_row-item{
    align-items: baseline !important;
    text-align: right;
    color: #666;
    /deep/.ivu-input-suffix i{
      color: #999;
      font-size: 18px;
    }
    .button{
       margin-top: 20px;
      &.on{
        margin-top: 0;
      }
      .bnt{
        width: 143px;
        height: 32px;
        border: 1px solid #DCDFE6;
        border-radius: 5px;
        font-size: 13px;
        cursor: pointer;
        .iconfont{
          font-size: 12px;
          color: #1890FF;
          margin-right: 5px;
        }
      }
    }
    .inputs{
      margin-bottom: 10px;
    }
  }
}
